        if R:
            c1,c2,c3,c4 = st.columns(4)
            c1.metric("Total SNPs",  len(R['snps']))
            c2.metric("Missense",    len(R['miss']))
            c3.metric("Nonsense",    len(R['non']))
            c4.metric("Identity",    f"{R['ident']:.1f}%")
            st.metric("Pathogenic Score", f"{R['path']}/100")
            st.progress(R['path']/100)
            mp = {m['pos'] for m in R['snps']}
            def color_mut(sq):
                out = ""
                for i,c in enumerate(sq[:80]):
                    if i+1 in mp: out += f'<span class="sm">{c}</span>'
                    elif c in "GC": out += f'<span class="sg">{c}</span>'
                    else: out += f'<span class="sa">{c}</span>'
                if len(sq)>80: out += f'<span style="color:#94A3B8"> +{len(sq)-80}</span>'
                return out
            c1,c2 = st.columns(2)
            with c1: st.markdown(f'<div class="card"><div style="font-size:10px;font-weight:700;color:#065F46;margin-bottom:6px">✅ Reference ({len(R["ref"])} bp)</div><div class="seq-block">{color_mut(R["ref"])}</div></div>', unsafe_allow_html=True)
            with c2: st.markdown(f'<div class="card"><div style="font-size:10px;font-weight:700;color:#92400E;margin-bottom:6px">🔬 Sample ({len(R["sam"])} bp)</div><div class="seq-block">{color_mut(R["sam"])}</div></div>', unsafe_allow_html=True)
            if R['snps']:
                st.markdown("#### Mutation Classification Table")
                st.dataframe([{"Pos":s['pos'],"Ref":s['r'],"Sample":s['s'],"Ref AA":s['ra'],"Sample AA":s['sa'],
                                "Class":"Nonsense" if s['non'] else ("Silent" if s['syn'] else "Missense")}
                               for s in R['snps'][:25]], use_container_width=True)
            if R['ld']!=0:
                ft = "Frameshift" if abs(R['ld'])%3!=0 else "In-frame"
                st.warning(f"**{ft} {'insertion' if R['ld']>0 else 'deletion'}** — {abs(R['ld'])} bp")

